-- SALY-only candidate creative knowledge repository and REVIEW_ONLY selector.
-- Exact body tested on PG17.12, PR #4595, run 44966305860, job 137036000236.
-- No official knowledge activation, render authorization, or runtime integration.
-- Approved scope: deploy via canonical Merge Train, owner clarified no separate Router invocation.
BEGIN;
DO $pre$ BEGIN
 IF (SELECT count(*) FROM saly.proyecto WHERE codigo='SALY-001' AND estado='ACTIVO')<>1 THEN RAISE EXCEPTION 'KNOWLEDGE_PROJECT_NOT_READY'; END IF;
 IF to_regclass('visual.knowledge_module_versions') IS NOT NULL THEN RAISE EXCEPTION 'KNOWLEDGE_RECONCILE_FIRST'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='pgcrypto') THEN RAISE EXCEPTION 'KNOWLEDGE_PGCRYPTO_REQUIRED'; END IF;
END $pre$;
CREATE TABLE visual.knowledge_module_versions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 business_code text NOT NULL CHECK (business_code='SALY'),
 module_code text NOT NULL CHECK (module_code ~ '^K[0-9]{2,}$'),
 version text NOT NULL CHECK (version ~ '^[0-9]+[.][0-9]+([.][0-9]+)?$'),
 parent_id bigint,
 document_id bigint NOT NULL UNIQUE REFERENCES saly.documentos(id) ON DELETE RESTRICT,
 document_sha256 text NOT NULL CHECK (document_sha256 ~ '^[a-f0-9]{64}$'),
 evidence_pins jsonb NOT NULL CHECK (jsonb_typeof(evidence_pins)='object' AND evidence_pins<>'{}'::jsonb),
 state text NOT NULL DEFAULT 'CANDIDATE' CHECK (state='CANDIDATE'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(business_code,module_code,version), UNIQUE(id,business_code,module_code),
 FOREIGN KEY(parent_id,business_code,module_code) REFERENCES visual.knowledge_module_versions(id,business_code,module_code) ON DELETE RESTRICT,
 CHECK(parent_id IS NULL OR parent_id<>id)
);
-- In this lot versions are append-only; future approval/revocation is a separate governed contract.
CREATE FUNCTION visual.knowledge_candidate_immutable_v1() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
BEGIN RAISE EXCEPTION 'KNOWLEDGE_CANDIDATE_IMMUTABLE'; END $f$;
CREATE TRIGGER knowledge_candidate_immutable BEFORE UPDATE OR DELETE ON visual.knowledge_module_versions
FOR EACH ROW EXECUTE FUNCTION visual.knowledge_candidate_immutable_v1();
ALTER TABLE visual.knowledge_module_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE visual.knowledge_module_versions FORCE ROW LEVEL SECURITY;
REVOKE ALL ON visual.knowledge_module_versions FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON SEQUENCE visual.knowledge_module_versions_id_seq FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION visual.knowledge_candidate_immutable_v1() FROM PUBLIC,anon,authenticated,service_role;
-- Evidence pin covers the actual stored claims, sources, state and limitations, not external article bytes.
CREATE FUNCTION visual.knowledge_evidence_digest_v1(e saly.evidencias) RETURNS text
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog AS $f$
 SELECT encode(extensions.digest(jsonb_build_object('codigo',(e).codigo,'tipo',(e).tipo,'titulo',(e).titulo,'descripcion',(e).descripcion,'referencia',(e).referencia,'fecha_evidencia',(e).fecha_evidencia,'hechos',(e).hechos,'estado',(e).estado)::text,'sha256'),'hex');
$f$;
REVOKE ALL ON FUNCTION visual.knowledge_evidence_digest_v1(saly.evidencias) FROM PUBLIC,anon,authenticated,service_role;

