-- Only callable in review, never via broad grants on saly.documentos/evidencias.
-- Fixed owner and strict filtering; future multi-business support requires a separate authority.
CREATE FUNCTION visual.knowledge_select_review_v1(p_business text,p_mode text,p_context jsonb,p_pins jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $f$
DECLARE task text; dense boolean; required text[]; related text[]; actual text[]; pin jsonb;
 v visual.knowledge_module_versions%ROWTYPE; d saly.documentos%ROWTYPE; e jsonb; result jsonb:='[]'::jsonb;
BEGIN
 IF p_business IS DISTINCT FROM 'SALY' OR p_mode IS DISTINCT FROM 'REVIEW_ONLY' THEN RAISE EXCEPTION 'KNOWLEDGE_SCOPE_OR_MODE'; END IF;
 IF jsonb_typeof(p_context) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_context))<>3 OR NOT (p_context ?& ARRAY['task','dense','related_modules']) OR jsonb_typeof(p_context->'task') IS DISTINCT FROM 'string' OR jsonb_typeof(p_context->'dense') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_context->'related_modules') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'KNOWLEDGE_CONTEXT_FIELDS'; END IF;
 task:=p_context->>'task'; dense:=(p_context->>'dense')::boolean;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_context->'related_modules') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR (x#>>'{}') NOT IN ('K01','K02','K03','K04','K05')) THEN RAISE EXCEPTION 'KNOWLEDGE_RELATED_MODULES'; END IF;
 SELECT coalesce(array_agg(x ORDER BY x),ARRAY[]::text[]) INTO related FROM (SELECT DISTINCT jsonb_array_elements_text(p_context->'related_modules') x) s;
 IF cardinality(related)<>jsonb_array_length(p_context->'related_modules') THEN RAISE EXCEPTION 'KNOWLEDGE_RELATED_MODULES'; END IF;
 IF task<>'AUDIT' AND cardinality(related)<>0 THEN RAISE EXCEPTION 'KNOWLEDGE_RELATED_MODULES'; END IF;
 CASE task
 WHEN 'NEW_DESIGN' THEN required:=ARRAY['K01','K02','K03','K05','K06'];
 WHEN 'ART_DIRECTION' THEN required:=ARRAY['K01','K02','K03','K05','K06'];
 WHEN 'SPACE_OPTIMIZATION' THEN required:=ARRAY['K03','K04','K05','K06'];
 WHEN 'LOCAL_CORRECTION' THEN required:=ARRAY['K05','K06']; IF dense THEN RAISE EXCEPTION 'KNOWLEDGE_CORRECTION_SCOPE'; END IF;
 WHEN 'AUDIT' THEN required:=related||ARRAY['K06'];
 ELSE RAISE EXCEPTION 'KNOWLEDGE_TASK_UNSUPPORTED'; END CASE;
 IF dense AND task IN ('NEW_DESIGN','ART_DIRECTION','AUDIT') THEN required:=required||ARRAY['K04']; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO required FROM unnest(required) x;
 IF jsonb_typeof(p_pins) IS DISTINCT FROM 'array' OR jsonb_array_length(p_pins)<>cardinality(required) THEN RAISE EXCEPTION 'KNOWLEDGE_PIN_SET'; END IF;
 FOR pin IN SELECT value FROM jsonb_array_elements(p_pins) LOOP
  IF jsonb_typeof(pin) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(pin))<>3 OR NOT (pin ?& ARRAY['module_code','version','sha256']) OR jsonb_typeof(pin->'module_code') IS DISTINCT FROM 'string' OR jsonb_typeof(pin->'version') IS DISTINCT FROM 'string' OR jsonb_typeof(pin->'sha256') IS DISTINCT FROM 'string' OR (pin->>'sha256') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'KNOWLEDGE_PIN_FIELDS'; END IF;
 END LOOP;
 SELECT array_agg(x->>'module_code' ORDER BY x->>'module_code') INTO actual FROM jsonb_array_elements(p_pins) x;
 IF actual IS DISTINCT FROM required THEN RAISE EXCEPTION 'KNOWLEDGE_PIN_SET'; END IF;
 FOR pin IN SELECT value FROM jsonb_array_elements(p_pins) ORDER BY value->>'module_code' LOOP
  SELECT * INTO v FROM visual.knowledge_module_versions WHERE business_code=p_business AND module_code=pin->>'module_code' AND version=pin->>'version' AND document_sha256=pin->>'sha256' AND state='CANDIDATE';
  IF NOT FOUND THEN RAISE EXCEPTION 'KNOWLEDGE_PIN_NOT_FOUND'; END IF;
  SELECT * INTO d FROM saly.documentos WHERE id=v.document_id;
  IF NOT FOUND OR d.sha256 IS DISTINCT FROM v.document_sha256 OR d.contenido IS NULL OR octet_length(d.contenido) IS DISTINCT FROM d.tamano_bytes OR encode(extensions.digest(d.contenido,'sha256'),'hex') IS DISTINCT FROM v.document_sha256 OR d.binario_persistido IS DISTINCT FROM true OR d.estado_persistencia IS DISTINCT FROM 'BINARIO_VERIFICADO' OR d.metadata->>'business_code' IS DISTINCT FROM p_business OR d.metadata->>'module_code' IS DISTINCT FROM v.module_code OR d.metadata->>'version' IS DISTINCT FROM v.version OR d.metadata->>'status' IS DISTINCT FROM 'CANDIDATE' THEN RAISE EXCEPTION 'KNOWLEDGE_DOCUMENT_DRIFT'; END IF;
  SELECT jsonb_object_agg(s.codigo,visual.knowledge_evidence_digest_v1(s)) INTO e FROM saly.evidencia_documentos l JOIN saly.evidencias s ON s.id=l.evidencia_id WHERE l.documento_id=d.id AND l.relacion='REFERENCIA_CONTRASTADA' AND s.estado='REFERENCIAL';
  IF e IS DISTINCT FROM v.evidence_pins THEN RAISE EXCEPTION 'KNOWLEDGE_EVIDENCE_DRIFT'; END IF;
  result:=result||jsonb_build_array(jsonb_build_object('module_code',v.module_code,'version',v.version,'sha256',v.document_sha256,'document_id',d.id,'state',v.state,'evidence_pins',e,'content',convert_from(d.contenido,'UTF8')));
 END LOOP;
 RETURN jsonb_build_object('schema_version','CREATIVE_KNOWLEDGE_REVIEW_V1','status','CANDIDATE_REVIEW_ONLY','business_code',p_business,'context',p_context,'modules',result,'production_approved',false,'render_authorized',false,'transfer_validated',false);
END $f$;
REVOKE ALL ON FUNCTION visual.knowledge_select_review_v1(text,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION visual.knowledge_select_review_v1(text,text,jsonb,jsonb) TO service_role;
DO $post$ BEGIN
 IF (SELECT count(*) FROM visual.knowledge_module_versions)<>6 OR EXISTS(SELECT 1 FROM visual.knowledge_module_versions WHERE state<>'CANDIDATE') THEN RAISE EXCEPTION 'KNOWLEDGE_SEED_COUNT'; END IF;
 IF has_function_privilege('anon','visual.knowledge_select_review_v1(text,text,jsonb,jsonb)','EXECUTE') OR has_function_privilege('authenticated','visual.knowledge_select_review_v1(text,text,jsonb,jsonb)','EXECUTE') OR has_table_privilege('service_role','visual.knowledge_module_versions','INSERT') THEN RAISE EXCEPTION 'KNOWLEDGE_ACL_DRIFT'; END IF;
END $post$;
COMMIT;
